(5659452, 821686, 86218, '<td valign="top">Very shallow depth of field..maybe a misunderstanding. I therefore only comment on the lighting and feel this is overexposed to the extent that detail in the spider is lost. Work in this when composing and exposing. Background play big part in all this</td>', 'Very shallow depth of field..maybe a misunderstanding. I therefore only comment on the lighting and feel this is overexposed to the extent that detail in the spider is lost. Work in this when composing and exposing. Background play big part in all this', '2009-09-23 15:15:43.000000', NULL, 1),
(5659454, 823040, 109353, '<td valign="top">I think a subject is missing there... 5</td>', 'I think a subject is missing there... 5', '2009-09-23 15:16:59.000000', NULL, 1),
