(5659852, 822801, 54446, '<td valign="top">Excellent entry for this challenge.  Super job on the focus and deep DOF.  Most impressive is the very eye pleasing exposure throughout.  Excellent point of view.  Technically excellent!  10</td>', 'Excellent entry for this challenge.  Super job on the focus and deep DOF.  Most impressive is the very eye pleasing exposure throughout.  Excellent point of view.  Technically excellent!  10', '2009-09-23 19:23:05.000000', NULL, 1),
(5659853, 822871, 54446, '<td valign="top">Very delightful still life image.  I find the DOF to be very deep and complete throughout the scene.  I hate the frame because it reduces the size of the viewable image.  Not sure why you would do that, as this image could be right up at the top of this challenge.  Nevertheless, a 10 from me.</td>', 'Very delightful still life image.  I find the DOF to be very deep and complete throughout the scene.  I hate the frame because it reduces the size of the viewable image.  Not sure why you would do that, as this image could be right up at the top of this challenge.  Nevertheless, a 10 from me.', '2009-09-23 19:23:15.000000', NULL, 1),
(5659865, 822939, 107190, '<td valign="top">I like the way the colored object in the foreground sets off the blue of the water - cool looking bridge, a little too distant to really appreciate though.</td>', 'I like the way the colored object in the foreground sets off the blue of the water - cool looking bridge, a little too distant to really appreciate though.', '2009-09-23 19:34:04.000000', NULL, 1),
