(5659870, 822898, 107190, '<td valign="top">I''m a sucker for trees in general and these are very lovely. Great blue/yellow combo and very cool up-shot.</td>', 'I''m a sucker for trees in general and these are very lovely. Great blue/yellow combo and very cool up-shot.', '2009-09-23 19:38:53.000000', NULL, 1),
(5659871, 822384, 107190, '<td valign="top">A different subject (always welcome). The lighting makes it seem ghostly too.</td>', 'A different subject (always welcome). The lighting makes it seem ghostly too.', '2009-09-23 19:39:57.000000', NULL, 1),
(5659873, 821871, 107190, '<td valign="top">The detail would be better if sharper</td>', 'The detail would be better if sharper', '2009-09-23 19:41:02.000000', NULL, 1),
