(5660047, 822946, 36065, '<td valign="top">No way this misses a ribbon.  Amazing composition and perfect for the challenge.  This one pulls a 10 from me.  Awesome.</td>', 'No way this misses a ribbon.  Amazing composition and perfect for the challenge.  This one pulls a 10 from me.  Awesome.', '2009-09-23 22:14:24.000000', NULL, 1),
(5660057, 822700, 36065, '<td valign="top">Always, always, always use the full size allowances that DPC gives you.  640px is already a ridiculously small size to see on most modern monitors, but this is even more difficult.  I like the image, but much of the detail is lost due to the small size.</td>', 'Always, always, always use the full size allowances that DPC gives you.  640px is already a ridiculously small size to see on most modern monitors, but this is even more difficult.  I like the image, but much of the detail is lost due to the small size.', '2009-09-23 22:17:37.000000', NULL, 1),
