(5660891, 822270, 33068, '<td valign="top">Looks like shallow dof to me.  Nice pic though.</td>', 'Looks like shallow dof to me.  Nice pic though.', '2009-09-24 17:06:44.000000', NULL, 1),
(5660938, 822882, 103142, '<td valign="top">The dof is well done, and that''s the hard part. Unfortunately, even though the foreground is in focus, it doesn''t hold much interest, imo. I like the back part of the photo, but the foreground didn''t add much. Sorry! (not voting yet)</td>', 'The dof is well done, and that''s the hard part. Unfortunately, even though the foreground is in focus, it doesn''t hold much interest, imo. I like the back part of the photo, but the foreground didn''t add much. Sorry! (not voting yet)', '2009-09-24 17:41:50.000000', NULL, 1),
(5660939, 822836, 103142, '<td valign="top">Well, Dorothy, I don''t think we''re in Kansas anymore!<br/> <br/>Nicely done. (not voting yet)</td>', 'Well, Dorothy, I don''t think we''re in Kansas anymore! Nicely done. (not voting yet)', '2009-09-24 17:41:59.000000', NULL, 1),
(5660940, 822744, 103142, '<td valign="top">Unfortunately, because we''re so limited in size, it''s hard for these bad eyes to see if the distance is focused or not. It looks like it is, so I''ll assume so. Unfortunately, there just really isn''t much to catch a person''s interest, imo... sorry! (not voting yet)</td>', 'Unfortunately, because we''re so limited in size, it''s hard for these bad eyes to see if the distance is focused or not. It looks like it is, so I''ll assume so. Unfortunately, there just really isn''t much to catch a person''s interest, imo... sorry! (not voting yet)', '2009-09-24 17:42:03.000000', NULL, 1),
(5660941, 822464, 103142, '<td valign="top">I wasn''t sure how deep the depth of field had to be in order to do well in this challenge. Imo, this is deep enough, and I find the photo very intriguing! (not voting yet)</td>', 'I wasn''t sure how deep the depth of field had to be in order to do well in this challenge. Imo, this is deep enough, and I find the photo very intriguing! (not voting yet)', '2009-09-24 17:42:06.000000', NULL, 1),
(5660945, 822982, 103142, '<td valign="top">I''m sorry, you''ve probably already heard this, but some people might be afraid to comment, and you might be wondering... Deep depth of field means that objects close in the frame and far away are both in focus. I''m sorry, it just doesn''t meet the challenge. (not voting yet)</td>', 'I''m sorry, you''ve probably already heard this, but some people might be afraid to comment, and you might be wondering... Deep depth of field means that objects close in the frame and far away are both in focus. I''m sorry, it just doesn''t meet the challenge. (not voting yet)', '2009-09-24 17:44:08.000000', NULL, 1),
(5660946, 822934, 103142, '<td valign="top">nice shot. Would have liked a little more breathing room for the cross. It''s cropped too tight.</td>', 'nice shot. Would have liked a little more breathing room for the cross. It''s cropped too tight.', '2009-09-24 17:44:55.000000', NULL, 1),
(5660948, 822939, 103142, '<td valign="top">This is very nicely done. The only recommendation I have is to find a more interesting foreground subject. The scenery is so incredibly beautiful, it makes you a little grumpy that the foreground is larger and not anywhere near as interesting. Maybe a crab part, or a abandoned, half broken toy, dead fish, (and maybe off to the side just a tad more).  :D  -7-</td>', 'This is very nicely done. The only recommendation I have is to find a more interesting foreground subject. The scenery is so incredibly beautiful, it makes you a little grumpy that the foreground is larger and not anywhere near as interesting. Maybe a crab part, or a abandoned, half broken toy, dead fish, (and maybe off to the side just a tad more).  :D  -7-', '2009-09-24 17:47:32.000000', NULL, 1),
(5660949, 822895, 103142, '<td valign="top">There we go!! I was just commenting on another shot with wonderful background but boring foreground, saying have something a little more interesting in the shot, and then I switched to this one! You found something much more interesting!  nicely done  -8-</td>', 'There we go!! I was just commenting on another shot with wonderful background but boring foreground, saying have something a little more interesting in the shot, and then I switched to this one! You found something much more interesting!  nicely done  -8-', '2009-09-24 17:48:34.000000', NULL, 1),
(5660950, 822978, 103142, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2009-09-24 17:48:56.000000', NULL, 1),
(5660951, 823021, 103142, '<td valign="top">I''m sorry, you''ve probably already heard this, but some people might be afraid to comment, and you might be wondering... Deep depth of field means that objects close in the frame and far away are both in focus. I''m sorry, it just doesn''t meet the challenge. (not voting yet)</td>', 'I''m sorry, you''ve probably already heard this, but some people might be afraid to comment, and you might be wondering... Deep depth of field means that objects close in the frame and far away are both in focus. I''m sorry, it just doesn''t meet the challenge. (not voting yet)', '2009-09-24 17:49:10.000000', NULL, 1),
(5660952, 823072, 103142, '<td valign="top">This is one of those images that don''t do well on first glance, but really grow on you. My first thought was 5--but I like the title, like the idea of toy and machine.  -7- I hope people give it more than a first glance!</td>', 'This is one of those images that don''t do well on first glance, but really grow on you. My first thought was 5--but I like the title, like the idea of toy and machine.  -7- I hope people give it more than a first glance!', '2009-09-24 17:50:30.000000', NULL, 1),
(5661068, 822814, 82749, '<td valign="top">Gorgeous image!</td>', 'Gorgeous image!', '2009-09-24 21:13:39.000000', NULL, 1),
(5661084, 822579, 99256, '<td valign="top">More contrast would have helped.  Also it seems a little blurry.  I can''t really tell how deep the DOF is because it''s all a little soft.</td>', 'More contrast would have helped.  Also it seems a little blurry.  I can''t really tell how deep the DOF is because it''s all a little soft.', '2009-09-24 21:29:08.000000', NULL, 1),
(5661090, 822815, 99256, '<td valign="top">Love the reflections and the dramatic angle.</td>', 'Love the reflections and the dramatic angle.', '2009-09-24 21:34:07.000000', NULL, 1),
(5661096, 822507, 99256, '<td valign="top">Great example of deep DOF.</td>', 'Great example of deep DOF.', '2009-09-24 21:39:06.000000', NULL, 1),
(5661102, 823005, 99256, '<td valign="top">looks like a little blur on the top left section there but even so it''s a great shot.  I love the angles and the color.</td>', 'looks like a little blur on the top left section there but even so it''s a great shot.  I love the angles and the color.', '2009-09-24 21:58:03.000000', NULL, 1),
(5661104, 822745, 99256, '<td valign="top">Nice DOF but the picture doesn''t really interest me.  Might be the bland colors that takes away from it for me.</td>', 'Nice DOF but the picture doesn''t really interest me.  Might be the bland colors that takes away from it for me.', '2009-09-24 22:00:24.000000', NULL, 1),
(5661106, 822976, 99256, '<td valign="top">Great shot.  For this challenge I would have like the front keys to be more in focus but this is such a good shot.  The depth of field is still very deep.  I hope people don''t count off too much because of the blur in the front but around here I bet they will.</td>', 'Great shot.  For this challenge I would have like the front keys to be more in focus but this is such a good shot.  The depth of field is still very deep.  I hope people don''t count off too much because of the blur in the front but around here I bet they will.', '2009-09-24 22:05:42.000000', NULL, 1),
(5661126, 822994, 39632, '<td valign="top">this is shallow DOF, not deep.</td>', 'this is shallow DOF, not deep.', '2009-09-24 22:28:34.000000', NULL, 1),
(5661160, 823034, 107190, '<td valign="top">This is so crisp and clean and a lovely angle with a good DOF perspective too. Very nice!</td>', 'This is so crisp and clean and a lovely angle with a good DOF perspective too. Very nice!', '2009-09-24 23:09:15.000000', NULL, 1),
(5661161, 823116, 107190, '<td valign="top">Original idea - nice DOF</td>', 'Original idea - nice DOF', '2009-09-24 23:09:22.000000', NULL, 1),
(5661180, 822815, 85849, '<td valign="top">I didn''t notice the clouds until I read the title. Definitely meets the challenge and it is interesting.</td>', 'I didn''t notice the clouds until I read the title. Definitely meets the challenge and it is interesting.', '2009-09-24 23:39:46.000000', NULL, 1),
(5661182, 822940, 85849, '<td valign="top">Very nice shot!</td>', 'Very nice shot!', '2009-09-24 23:40:25.000000', NULL, 1),
(5661183, 823012, 85849, '<td valign="top">That''s quite the view!</td>', 'That''s quite the view!', '2009-09-24 23:41:29.000000', NULL, 1),
(5661185, 822898, 85849, '<td valign="top">I''ve tried shots like this, but never really managed to do well. This is quite nicely done!</td>', 'I''ve tried shots like this, but never really managed to do well. This is quite nicely done!', '2009-09-24 23:43:18.000000', NULL, 1),
(5661186, 822992, 85849, '<td valign="top">This is an interesting shot, but I''m not sure it demonstrates a deep depth of field.</td>', 'This is an interesting shot, but I''m not sure it demonstrates a deep depth of field.', '2009-09-24 23:44:21.000000', NULL, 1),
(5661188, 823119, 85849, '<td valign="top">Quite literally the depth of the field ;) I find it needs a main subject other than just the field. Even if it were a farmers field with bales of hay or maybe a farmhouse.</td>', 'Quite literally the depth of the field ;) I find it needs a main subject other than just the field. Even if it were a farmers field with bales of hay or maybe a farmhouse.', '2009-09-24 23:48:38.000000', NULL, 1),
(5661191, 823005, 85849, '<td valign="top">The building is quite nice. I find there''s something not quite right about the sky though. I wonder if the white balance was off. The shade and amount of blue seems unreal. Especially to the top right.</td>', 'The building is quite nice. I find there''s something not quite right about the sky though. I wonder if the white balance was off. The shade and amount of blue seems unreal. Especially to the top right.', '2009-09-24 23:52:05.000000', NULL, 1),
(5661194, 823082, 85849, '<td valign="top">I would call this a shallow depth of field.</td>', 'I would call this a shallow depth of field.', '2009-09-24 23:53:43.000000', NULL, 1),
(5661197, 822737, 85849, '<td valign="top">WOW! Beautiful shoreline!</td>', 'WOW! Beautiful shoreline!', '2009-09-24 23:54:07.000000', NULL, 1),
(5661202, 823030, 85849, '<td valign="top">Beautiful waters and I love the sailboat waaay off in the distance!</td>', 'Beautiful waters and I love the sailboat waaay off in the distance!', '2009-09-24 23:55:16.000000', NULL, 1),
(5661204, 822270, 85849, '<td valign="top">Very nice shot, but not a deep depth of field.</td>', 'Very nice shot, but not a deep depth of field.', '2009-09-24 23:56:31.000000', NULL, 1),
(5661209, 823034, 85849, '<td valign="top">OK - the most interesting so far. I''ll give this one a ten!</td>', 'OK - the most interesting so far. I''ll give this one a ten!', '2009-09-24 23:58:20.000000', NULL, 1),
(5661212, 821858, 85849, '<td valign="top">WOW - some really nice scenes in this contest!</td>', 'WOW - some really nice scenes in this contest!', '2009-09-24 23:58:57.000000', NULL, 1),
(5661215, 823116, 85849, '<td valign="top">This looks like an HDR shot. I''ll have to asssume it meets the editing rules and give it a ten. How did you possibly get this so sharp and well lit?</td>', 'This looks like an HDR shot. I''ll have to asssume it meets the editing rules and give it a ten. How did you possibly get this so sharp and well lit?', '2009-09-25 00:01:14.000000', NULL, 1),
(5661217, 821686, 85849, '<td valign="top">This is a shallow DOF and it seems quite over exposed.</td>', 'This is a shallow DOF and it seems quite over exposed.', '2009-09-25 00:03:07.000000', NULL, 1),
(5661220, 822836, 85849, '<td valign="top">Does that tree ever pop out and the balloon looks like it''s there to watch the match. Very nice!</td>', 'Does that tree ever pop out and the balloon looks like it''s there to watch the match. Very nice!', '2009-09-25 00:04:08.000000', NULL, 1),
(5661221, 823086, 85849, '<td valign="top">What a cool sky not to mention everything else!</td>', 'What a cool sky not to mention everything else!', '2009-09-25 00:05:37.000000', NULL, 1),
(5661222, 823056, 85849, '<td valign="top">I''m not sure the fisheye adds to the image. Nice sky!</td>', 'I''m not sure the fisheye adds to the image. Nice sky!', '2009-09-25 00:08:47.000000', NULL, 1),
(5661226, 822595, 85849, '<td valign="top">A nice lagoon!</td>', 'A nice lagoon!', '2009-09-25 00:11:18.000000', NULL, 1),
(5661229, 822946, 85849, '<td valign="top">Very nice!</td>', 'Very nice!', '2009-09-25 00:12:42.000000', NULL, 1),
(5661233, 823014, 85849, '<td valign="top">The sky is a little blown out not bad otherwise.</td>', 'The sky is a little blown out not bad otherwise.', '2009-09-25 00:14:02.000000', NULL, 1),
(5661234, 823077, 85849, '<td valign="top">...eat them up ...yummm</td>', '...eat them up ...yummm', '2009-09-25 00:14:53.000000', NULL, 1),
(5661243, 823082, 81362, '<td valign="top">Use of shallow depth of field works well for the image - keeping the grasshopper and first thistle sharp, making a moderate blur for the two further thistles, and really obscuring the background. It gives a sense of three dimensionality and simplifies the composition so we pay attention to the main subject. But I would expect low votes in a challenge asking for deep depth of field.</td>', 'Use of shallow depth of field works well for the image - keeping the grasshopper and first thistle sharp, making a moderate blur for the two further thistles, and really obscuring the background. It gives a sense of three dimensionality and simplifies the composition so we pay attention to the main subject. But I would expect low votes in a challenge asking for deep depth of field.', '2009-09-25 00:20:22.000000', NULL, 1),
(5661247, 823115, 85849, '<td valign="top">That''s a pretty deep DOF for such action going on. Very nice!<br/> <br/>Looking closer, I would have cropped to lose all or most of the blue house to the left. It increases the drammatic effect and, I think, still shows the deep DOF. I say this because of my interest in the shot, not as criticism and it''s just one person''s opinion ;-)</td>', 'That''s a pretty deep DOF for such action going on. Very nice! Looking closer, I would have cropped to lose all or most of the blue house to the left. It increases the drammatic effect and, I think, still shows the deep DOF. I say this because of my interest in the shot, not as criticism and it''s just one person''s opinion ;-)', '2009-09-25 00:22:36.000000', NULL, 1),
(5661251, 822814, 85849, '<td valign="top">We have ribbon contender number two!!!</td>', 'We have ribbon contender number two!!!', '2009-09-25 00:24:34.000000', NULL, 1),
(5661252, 822995, 85849, '<td valign="top">It''s too bad about the haze. This would be just beautiful on the right day!</td>', 'It''s too bad about the haze. This would be just beautiful on the right day!', '2009-09-25 00:25:32.000000', NULL, 1),
(5661254, 823092, 85849, '<td valign="top">A little too much shooting into the sun. It''s just overpowering the image.</td>', 'A little too much shooting into the sun. It''s just overpowering the image.', '2009-09-25 00:27:21.000000', NULL, 1),
(5661255, 823037, 85849, '<td valign="top">aaahhhhh... paradise!</td>', 'aaahhhhh... paradise!', '2009-09-25 00:27:54.000000', NULL, 1),
(5661256, 822920, 85849, '<td valign="top">An interesting forground, but the background is so busy.</td>', 'An interesting forground, but the background is so busy.', '2009-09-25 00:29:04.000000', NULL, 1),
(5661257, 823101, 85849, '<td valign="top">Quick! Someone give her the heimlich!<br/> <br/>Very cool shot!</td>', 'Quick! Someone give her the heimlich! Very cool shot!', '2009-09-25 00:30:41.000000', NULL, 1),
(5661259, 822063, 85849, '<td valign="top">very dark</td>', 'very dark', '2009-09-25 00:31:20.000000', NULL, 1),
(5661261, 822572, 85849, '<td valign="top">another amazing scene!</td>', 'another amazing scene!', '2009-09-25 00:31:48.000000', NULL, 1),
(5661268, 821871, 64446, '<td valign="top">Nice image, but the dof is in fact shallow.</td>', 'Nice image, but the dof is in fact shallow.', '2009-09-25 00:52:02.000000', NULL, 1),
(5661507, 823006, 109353, '<td valign="top">I can''t understand the link with title of the challenge ... if you can help me.</td>', 'I can''t understand the link with title of the challenge ... if you can help me.', '2009-09-25 04:22:41.000000', NULL, 1),
(5661535, 823136, 80908, '<td valign="top">Great DOF, but the composition seems a little unbalanced and the near boat is very blown out.</td>', 'Great DOF, but the composition seems a little unbalanced and the near boat is very blown out.', '2009-09-25 05:50:39.000000', NULL, 1),
(5661536, 822409, 80908, '<td valign="top">Great shot - really nice composition and clarity with excellent DOF. Also, that sheep is giving you a really suspicious look! 9</td>', 'Great shot - really nice composition and clarity with excellent DOF. Also, that sheep is giving you a really suspicious look! 9', '2009-09-25 05:51:35.000000', NULL, 1),
(5661537, 823135, 80908, '<td valign="top">Nice idea and good DOF.</td>', 'Nice idea and good DOF.', '2009-09-25 05:52:15.000000', NULL, 1),
(5661538, 822038, 80908, '<td valign="top">Good DOF, shame about the lack of definition. Nice composition but could benefit from more contrast to make it ''pop''</td>', 'Good DOF, shame about the lack of definition. Nice composition but could benefit from more contrast to make it ''pop''', '2009-09-25 05:53:44.000000', NULL, 1),
(5661539, 823140, 80908, '<td valign="top">Nice landscape shot, but nothing specific to grab my attention. Good long DOF!</td>', 'Nice landscape shot, but nothing specific to grab my attention. Good long DOF!', '2009-09-25 05:55:04.000000', NULL, 1),
(5661540, 823133, 80908, '<td valign="top">Very strange processing which detracts from this shot.  Not sure how it demonstrates long DOF.</td>', 'Very strange processing which detracts from this shot.  Not sure how it demonstrates long DOF.', '2009-09-25 05:55:49.000000', NULL, 1),
(5661541, 822996, 80908, '<td valign="top">Nice shot, nicely produced and processed but doesn''t demonstrate (for me) the kind of DOF I think this challenge requires. 6</td>', 'Nice shot, nicely produced and processed but doesn''t demonstrate (for me) the kind of DOF I think this challenge requires. 6', '2009-09-25 05:56:56.000000', NULL, 1),
(5661543, 823099, 80908, '<td valign="top">A classic DPC evening colours shot.  Unfortunately impossible to see if anything close up is in focus proving a long DOF!</td>', 'A classic DPC evening colours shot.  Unfortunately impossible to see if anything close up is in focus proving a long DOF!', '2009-09-25 05:59:42.000000', NULL, 1),
(5661544, 823132, 80908, '<td valign="top">Excellent colours and clarity, nicely done also on the DOF!</td>', 'Excellent colours and clarity, nicely done also on the DOF!', '2009-09-25 06:01:59.000000', NULL, 1),
(5661545, 823088, 80908, '<td valign="top">A little over-sharpened, also impossible to tell if the foreground is in focus and prove a long DOF.</td>', 'A little over-sharpened, also impossible to tell if the foreground is in focus and prove a long DOF.', '2009-09-25 06:03:05.000000', NULL, 1),
(5661546, 822898, 80908, '<td valign="top">Beautiful, and fits the challenge perfectly.</td>', 'Beautiful, and fits the challenge perfectly.', '2009-09-25 06:04:20.000000', NULL, 1),
(5661547, 822717, 80908, '<td valign="top">Very peaceful shot. DMC. Nice moody levels of light.</td>', 'Very peaceful shot. DMC. Nice moody levels of light.', '2009-09-25 06:05:06.000000', NULL, 1),
(5661548, 823116, 80908, '<td valign="top">Looks like a leftover from the HDR II challenge! Good DOF but I find the cartoon effect offputting. With this title I think the car park needs a grungy look, rather than the nice clean well lit look you have given it.</td>', 'Looks like a leftover from the HDR II challenge! Good DOF but I find the cartoon effect offputting. With this title I think the car park needs a grungy look, rather than the nice clean well lit look you have given it.', '2009-09-25 06:06:40.000000', NULL, 1),
(5661549, 822465, 80908, '<td valign="top">Interesting and well composed but does not demonstrate long DOF.</td>', 'Interesting and well composed but does not demonstrate long DOF.', '2009-09-25 06:07:07.000000', NULL, 1),
(5661550, 822995, 80908, '<td valign="top">Stunning area. Some sharpening artefacts top left but really nice DOF.</td>', 'Stunning area. Some sharpening artefacts top left but really nice DOF.', '2009-09-25 06:07:51.000000', NULL, 1),
(5661551, 822221, 80908, '<td valign="top">Erm... interesting but does not seem to demonstrate deep DOF? Unless I am missing something.</td>', 'Erm... interesting but does not seem to demonstrate deep DOF? Unless I am missing something.', '2009-09-25 06:08:27.000000', NULL, 1),
(5661552, 822096, 80908, '<td valign="top">Nice moody shot, almost too dark although perhaps this monitor is not quite set right. Great DOF.</td>', 'Nice moody shot, almost too dark although perhaps this monitor is not quite set right. Great DOF.', '2009-09-25 06:09:08.000000', NULL, 1),
(5661553, 822982, 80908, '<td valign="top">I get the title, and the pun but I would have preferred to see a deep DOF. Sorry!</td>', 'I get the title, and the pun but I would have preferred to see a deep DOF. Sorry!', '2009-09-25 06:09:59.000000', NULL, 1),
(5661554, 822335, 80908, '<td valign="top">Nice composition but uninspiring colours - perhaps could have worked as a BW? Reasonable DOF though.</td>', 'Nice composition but uninspiring colours - perhaps could have worked as a BW? Reasonable DOF though.', '2009-09-25 06:11:09.000000', NULL, 1),
(5661555, 822588, 80908, '<td valign="top">Great composition, really grabs the moment.</td>', 'Great composition, really grabs the moment.', '2009-09-25 06:11:49.000000', NULL, 1),
(5661556, 823080, 80908, '<td valign="top">This really needs a closer subject to demonstrate ''deep'' DOF.  It is a pleasant photo but not arresting.</td>', 'This really needs a closer subject to demonstrate ''deep'' DOF.  It is a pleasant photo but not arresting.', '2009-09-25 06:12:52.000000', NULL, 1),
(5661557, 822994, 80908, '<td valign="top">Great demonstration of a really shallow DOF.</td>', 'Great demonstration of a really shallow DOF.', '2009-09-25 06:16:07.000000', NULL, 1),
(5661559, 822921, 80908, '<td valign="top">Nice shot, good composition and lighting and a nice sense of dynamism.</td>', 'Nice shot, good composition and lighting and a nice sense of dynamism.', '2009-09-25 06:22:25.000000', NULL, 1),
(5661560, 822976, 80908, '<td valign="top">Lovely moody shot with great perspective and composition, but doesn''t demonstrate deep DOF.</td>', 'Lovely moody shot with great perspective and composition, but doesn''t demonstrate deep DOF.', '2009-09-25 06:23:14.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5661562, 823127, 80908, '<td valign="top">Good demonstration of deep(ish) DOF but the composition is a little uninspiring.</td>', 'Good demonstration of deep(ish) DOF but the composition is a little uninspiring.', '2009-09-25 06:25:27.000000', NULL, 1),
