(5661823, 823002, 110370, '<td valign="top">Photo is not sharp at all. The composition and POV do not work for me here. sorry.</td>', 'Photo is not sharp at all. The composition and POV do not work for me here. sorry.', '2009-09-25 10:02:37.000000', NULL, 1),
(5661827, 823115, 110370, '<td valign="top">Good timing. But the crop is not good here. It would be good to see both boys in frmae.</td>', 'Good timing. But the crop is not good here. It would be good to see both boys in frmae.', '2009-09-25 10:03:52.000000', NULL, 1),
