(5661853, 822844, 57447, '<td valign="top">I like the way the fence leads the eye through the photo.</td>', 'I like the way the fence leads the eye through the photo.', '2009-09-25 10:14:56.000000', NULL, 1),
(5661857, 823086, 57447, '<td valign="top">Meets challenge criteria better than many others.</td>', 'Meets challenge criteria better than many others.', '2009-09-25 10:15:56.000000', NULL, 1),
