(5669426, 822572, 86447, '<td valign="top">Beautiful, Mark!   Congrats on your ribbon and your Seasons Trio.</td>', 'Beautiful, Mark!   Congrats on your ribbon and your Seasons Trio.', '2009-10-01 13:37:04.000000', NULL, 0),
