(5669535, 822814, 67237, '<td valign="top">congrats on the excellent image!!. I know how it feels to reach 7.4+ and no ribbon.<br/> <br/>about the re-edit. In order to make a fair election , post it at 640px and confirm it is also edited under basic editing rules. send a pm when it''s done (I mean in case you decide to do it).</td>', 'congrats on the excellent image!!. I know how it feels to reach 7.4+ and no ribbon. about the re-edit. In order to make a fair election , post it at 640px and confirm it is also edited under basic editing rules. send a pm when it''s done (I mean in case you decide to do it).', '2009-10-01 15:05:29.000000', NULL, 0),
(5669664, 822814, 67237, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by nutzito:</b></div><hr/><i> congrats on the excellent image!!. I know how it feels to reach 7.4+ and no ribbon.<br/> <br/>about the re-edit. In order to make a fair election , post it at 640px and confirm it is also edited under basic editing rules. send a pm when it''s done (I mean in case you decide to do it). </i></td></tr></table> <br/> <br/>OK. Although the re-edit version has more realistic hues, I like the color palette of the one you entered better. It gives a more mysterious look and I think that goes better with the object of the technic you used. That said, I think the wow factor of the one you entered is better.<br/> <br/>Edit: Forgot to mention that when I said "realistic" I was thinking of sunlight, but you are creating artificial darkness here so  I like the darkness and consistent cooler tones of the first one better.<br/><br/><i>Message edited by author 2009-10-01 15:01:58.</i></td>', 'Originally posted by nutzito: congrats on the excellent image!!. I know how it feels to reach 7.4+ and no ribbon. about the re-edit. In order to make a fair election , post it at 640px and confirm it is also edited under basic editing rules. send a pm when it''s done (I mean in case you decide to do it).   OK. Although the re-edit version has more realistic hues, I like the color palette of the one you entered better. It gives a more mysterious look and I think that goes better with the object of the technic you used. That said, I think the wow factor of the one you entered is better. Edit: Forgot to mention that when I said "realistic" I was thinking of sunlight, but you are creating artificial darkness here so  I like the darkness and consistent cooler tones of the first one better.', '2009-10-01 15:54:03.000000', '2009-10-01 16:01:58.000000', 0),
(5669668, 822814, 102386, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by nutzito:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by nutzito:</b></div><hr/><i> congrats on the excellent image!!. I know how it feels to reach 7.4+ and no ribbon.<br/> <br/>about the re-edit. In order to make a fair election , post it at 640px and confirm it is also edited under basic editing rules. send a pm when it''s done (I mean in case you decide to do it). </i></td></tr></table> <br/> <br/>OK. Although the re-edit version has more realistic hues, I like the color palette of the one you entered better. It gives a more mysterious look and I think that goes better with the object of the technic you used. That said, I think the wow factor of the one you entered is better. </i></td></tr></table> <br/> <br/>Thanks for the feedback. Appreciated.</td>', 'Originally posted by nutzito: Originally posted by nutzito: congrats on the excellent image!!. I know how it feels to reach 7.4+ and no ribbon. about the re-edit. In order to make a fair election , post it at 640px and confirm it is also edited under basic editing rules. send a pm when it''s done (I mean in case you decide to do it).   OK. Although the re-edit version has more realistic hues, I like the color palette of the one you entered better. It gives a more mysterious look and I think that goes better with the object of the technic you used. That said, I think the wow factor of the one you entered is better.   Thanks for the feedback. Appreciated.', '2009-10-01 15:56:17.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5669936, 823086, 66635, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2009-10-01 17:55:26.000000', NULL, 0),
(5670189, 823096, 6306, '<td valign="top">Nice light, but I am not a fan of the foreground.</td>', 'Nice light, but I am not a fan of the foreground.', '2009-10-01 20:53:38.000000', NULL, 0),
(5671991, 822409, 82749, '<td valign="top">The expression on the sheep''s face is wonderful!  Hoping we will see more of him in the future.</td>', 'The expression on the sheep''s face is wonderful!  Hoping we will see more of him in the future.', '2009-10-02 21:27:43.000000', NULL, 0),
(5672098, 822737, 42013, '<td valign="top">Congrats on your HM! You have some very nice shots in your zenfolio</td>', 'Congrats on your HM! You have some very nice shots in your zenfolio', '2009-10-02 22:31:44.000000', NULL, 0),
(5672914, 823096, 87278, '<td valign="top">Fabulous for me! It packs a supermarket of space in a single shot! Congrats on the blue!<br/>Goes into my favs!</td>', 'Fabulous for me! It packs a supermarket of space in a single shot! Congrats on the blue!Goes into my favs!', '2009-10-03 12:16:23.000000', NULL, 0),
(5673636, 823096, 4793, '<td valign="top">Nice shot</td>', 'Nice shot', '2009-10-03 22:24:01.000000', NULL, 0),
(5674055, 822978, 33535, '<td valign="top">Hooray to the TS!<br/>...and your ability to put it to good use. ;-)<br/>Cool shot!</td>', 'Hooray to the TS!...and your ability to put it to good use. ;-)Cool shot!', '2009-10-04 08:56:17.000000', NULL, 0),
(5675220, 822737, 65592, '<td valign="top">Thank you Mark, i am very honored for your words. You are an amazing photographer.</td>', 'Thank you Mark, i am very honored for your words. You are an amazing photographer.', '2009-10-05 04:44:15.000000', NULL, 0),
(5677038, 822464, 62357, '<td valign="top">Greetings from the Critique Club<br/> <br/>First of all, let me congratulate you for getting such a good score in this challenge, it was well deserved.<br/> <br/>I did not vote in this challenge but would likely have voted 7 or 8 as I really like this image a lot.<br/> <br/>I do think however, that for a few of the voters they were not seeing the deep DOF very well and that''s likely why you didn''t score even higher.<br/> <br/>I love the lighting, the composition and the muted colours are excellent.  It''s certainly a very interesting building.<br/> <br/>I found it quite difficult to critique this image well, because I like the image so much.  <br/> <br/>Well done again.</td>', 'Greetings from the Critique Club First of all, let me congratulate you for getting such a good score in this challenge, it was well deserved. I did not vote in this challenge but would likely have voted 7 or 8 as I really like this image a lot. I do think however, that for a few of the voters they were not seeing the deep DOF very well and that''s likely why you didn''t score even higher. I love the lighting, the composition and the muted colours are excellent.  It''s certainly a very interesting building. I found it quite difficult to critique this image well, because I like the image so much.   Well done again.', '2009-10-06 16:18:17.000000', NULL, 0),
(5677044, 822895, 62357, '<td valign="top">Greetings from the Critique Club<br/> <br/>I like the choice of subject and the composition of this image for the Deep DOF challenge.  You have certainly met the challenge.<br/> <br/>However, I do find that the image is lacking a certain something when it comes to the exposure.  Looking at your camera settings, I think I may have been tempted to reduce the ISO down to 100.  As far as I can tell with an 8 second exposure you are probably using a tripod, so if you had tried the ISO at 100, I believe you may have reduced the digital noise that is prevalent in the foreground of the image.<br/> <br/>I do think if you had adjusted the contrast in post processing that you may have overcome some of the noise issue.<br/> <br/>Overall I thought this was a good choice of subject for this challenge, the depth of field is great, but the exposure and post processing let this one down.  Definitely it did not realise it''s full potential.</td>', 'Greetings from the Critique Club I like the choice of subject and the composition of this image for the Deep DOF challenge.  You have certainly met the challenge. However, I do find that the image is lacking a certain something when it comes to the exposure.  Looking at your camera settings, I think I may have been tempted to reduce the ISO down to 100.  As far as I can tell with an 8 second exposure you are probably using a tripod, so if you had tried the ISO at 100, I believe you may have reduced the digital noise that is prevalent in the foreground of the image. I do think if you had adjusted the contrast in post processing that you may have overcome some of the noise issue. Overall I thought this was a good choice of subject for this challenge, the depth of field is great, but the exposure and post processing let this one down.  Definitely it did not realise it''s full potential.', '2009-10-06 16:26:39.000000', NULL, 0),
(5679157, 822409, 28742, '<td valign="top">Love this shot, roz! Great finish!</td>', 'Love this shot, roz! Great finish!', '2009-10-07 19:55:13.000000', NULL, 0),
(5679700, 822409, 69008, '<td valign="top">This is pretty cool the way the wide angle and your processing seems to bring the star of this show to the front, with an almost 3D effect.</td>', 'This is pretty cool the way the wide angle and your processing seems to bring the star of this show to the front, with an almost 3D effect.', '2009-10-08 01:21:30.000000', NULL, 0),
(5679945, 822898, 82707, '<td valign="top">Wow!  Congrats on top ten!  I love the composition and beautiful colours!</td>', 'Wow!  Congrats on top ten!  I love the composition and beautiful colours!', '2009-10-08 03:44:41.000000', NULL, 0),
(5680437, 822572, 29011, '<td valign="top">Beautiful. Though the Autumn version has always been my favorite, I do really like this one as well. The bits of warm light reflecting off of the top of the peaks just makes this extra special. Splendid work.</td>', 'Beautiful. Though the Autumn version has always been my favorite, I do really like this one as well. The bits of warm light reflecting off of the top of the peaks just makes this extra special. Splendid work.', '2009-10-08 11:59:47.000000', NULL, 0),
(5681758, 823077, 32767, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=459387" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/0-999/626/120/Copyrighted_Image_Reuse_Prohibited_459387.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/0-999/626/120/Copyrighted_Image_Reuse_Prohibited_459387.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/0-999/626/120/Copyrighted_Image_Reuse_Prohibited_459387.jpg"/></a></td>', '', '2009-10-09 14:20:43.000000', NULL, 0),
(5697978, 822836, 67152, '<td valign="top">I think this is a well composed and delivered shot.  I think where this one misses out a bit in the deep DOF is no subject really close to us.  The cricket players, the trees and the balloon are all far away from the camera.  Altering the composition by having something like a cricket bat on the ground close to the camera in the foreground, the players behind, and the balloow way out (all in sharp focus) would probably have garnered you a ribbon.</td>', 'I think this is a well composed and delivered shot.  I think where this one misses out a bit in the deep DOF is no subject really close to us.  The cricket players, the trees and the balloon are all far away from the camera.  Altering the composition by having something like a cricket bat on the ground close to the camera in the foreground, the players behind, and the balloow way out (all in sharp focus) would probably have garnered you a ribbon.', '2009-10-23 10:04:03.000000', NULL, 0),
(5700677, 823086, 46177, '<td valign="top">This is gorgeous! Straight to fav''s.</td>', 'This is gorgeous! Straight to fav''s.', '2009-10-26 07:50:54.000000', NULL, 0),
(5716655, 823050, 104230, '<td valign="top">Wonderful composition.  My father grew up in Liverpool and North Wales and I remember being taken to this cathedral while it was under construction during a family holiday, probably in the late 1950''s or early 1960''s.</td>', 'Wonderful composition.  My father grew up in Liverpool and North Wales and I remember being taken to this cathedral while it was under construction during a family holiday, probably in the late 1950''s or early 1960''s.', '2009-11-06 17:00:57.000000', NULL, 0),
(5749893, 822464, 73942, '<td valign="top">I gave this a 9 during the challenge, I loved it.  It reminds me of the staircase at Chateau Chambord  (I''m pretty sure that''s the right castle, it''s been years since I''ve been there).  Beautiful.</td>', 'I gave this a 9 during the challenge, I loved it.  It reminds me of the staircase at Chateau Chambord  (I''m pretty sure that''s the right castle, it''s been years since I''ve been there).  Beautiful.', '2009-12-02 07:55:48.000000', NULL, 0),
(5778647, 822898, 66635, '<td valign="top">This is spectacular!  Love the colors and perspective!</td>', 'This is spectacular!  Love the colors and perspective!', '2009-12-23 01:26:15.000000', NULL, 0),
(5883921, 822574, 30982, '<td valign="top">Wow.  WOW.  This is breathtaking!  Beautiful scene and you captured it and presented it magnificently!</td>', 'Wow.  WOW.  This is breathtaking!  Beautiful scene and you captured it and presented it magnificently!', '2010-02-28 22:30:00.000000', NULL, 0),
(5938269, 822905, 108351, '<td valign="top">Less than a year after I took this shot all the fences have been replaced with nice straight boring ones.</td>', 'Less than a year after I took this shot all the fences have been replaced with nice straight boring ones.', '2010-04-09 01:50:22.000000', NULL, 0),
