(5975198, 822774, 66635, '<td valign="top">I love it!</td>', 'I love it!', '2010-04-27 21:11:58.000000', NULL, 0),
(6050463, 823012, 34659, '<td valign="top">Awesome perspective!  Love the POV.  Composition is spot on!</td>', 'Awesome perspective!  Love the POV.  Composition is spot on!', '2010-06-10 19:31:04.000000', NULL, 0),
(6090237, 823096, 117831, '<td valign="top">WOW!!!!</td>', 'WOW!!!!', '2010-07-12 22:27:40.000000', NULL, 0),
(6108727, 823011, 40718, '<td valign="top">I don''t think this was a "boring subject".  I like your eye for things.  Probably the small canvas DPC offers let you down more than anything.  It does make the BG people small and insignificant.  If you had too much going on on the right, however, it would detract from the subject.  The sky is awesome and I love clouds like this.  Do you use any Wide-radius USM on your shots?  You have to watch for halos, but it might provide just a bit of contrast kick to the clouds (and you could mask whatever you didn''t like).  I usually start around 25/40/3.  Give it a try.</td>', 'I don''t think this was a "boring subject".  I like your eye for things.  Probably the small canvas DPC offers let you down more than anything.  It does make the BG people small and insignificant.  If you had too much going on on the right, however, it would detract from the subject.  The sky is awesome and I love clouds like this.  Do you use any Wide-radius USM on your shots?  You have to watch for halos, but it might provide just a bit of contrast kick to the clouds (and you could mask whatever you didn''t like).  I usually start around 25/40/3.  Give it a try.', '2010-07-29 16:16:30.000000', NULL, 0),
(6462827, 822844, 12611, '<td valign="top">Love this shot; the sky is nice and foreboding and the grass is perfect. such great feel/</td>', 'Love this shot; the sky is nice and foreboding and the grass is perfect. such great feel/', '2011-07-06 09:24:37.000000', NULL, 0),
(6949904, 823011, 152252, '<td valign="top">Okay even if you took a picture like that with a spinach booth instead of corndogs I''m sure it would still attract all the children :) Amazing clouds and colors</td>', 'Okay even if you took a picture like that with a spinach booth instead of corndogs I''m sure it would still attract all the children :) Amazing clouds and colors', '2013-01-05 18:53:12.000000', NULL, 0);
